ROOT.scriptdef:
set nocount on;

	update cdn.OpeZakazy set OpZ_ProcID = 30073 where OpZ_ProcID = 30784 and OpZ_OpeNumer NOT IN (select Opz_OpeNumer from cdn.OpeZakazy where OpZ_ProcID = 30073)

	update cdn.StaZakazy set StZ_ProcID = 30073 where StZ_ProcID = 30784 and StZ_StaNumer NOT IN (select StZ_StaNumer from cdn.StaZakazy where StZ_ProcID = 30073)

set nocount off;
